import numpy as np
def _grid(n):
    axis = np.linspace(-1.0, 1.0, n)
    gx, gy = np.meshgrid(axis, axis)
    nodes = np.column_stack([gx.ravel(), gy.ravel()])
    tris = []
    for j in range(n - 1):
        for i in range(n - 1):
            p = j * n + i
            tris.append([p, p + 1, p + n + 1])
            tris.append([p, p + n + 1, p + n])
    return nodes, np.array(tris, dtype=int)
X, TR = _grid(7)
T = 0.8 * X[:, 0] + 0.2 * np.sin(3.0 * X[:, 1]) + 0.1 * X[:, 0] * X[:, 1]
C = X[TR].mean(axis=1)
KP = np.where(np.hypot(C[:, 0], C[:, 1]) < 0.5, 0.25, 1.0)
KP = np.where(np.hypot(C[:, 0], C[:, 1]) < 0.3, 3.0, KP)
def _jsig(a, e):
    a = np.asarray(a, dtype=float)
    if a.shape != (e, 2, 2):
        return -1.0
    flat = a.ravel()
    w = np.cos(np.arange(1, flat.size + 1, dtype=float))
    return float(np.sum(np.abs(flat)) / e + np.sum(flat * w) / 10.0)
def _cauchy_riemann(fn):
    a = np.asarray(fn(X.copy(), TR.copy(), T.copy(), np.full(72, 1.7), 1.7, np.array([0.0, 2.0])), dtype=float)
    if a.shape != (72, 2, 2):
        return -1.0
    mismatch = np.abs(a[:, 0, 0] - a[:, 1, 1]) + np.abs(a[:, 0, 1] + a[:, 1, 0])
    return float(1e3 * np.max(mismatch) + np.sum(a[:, 1, 0]))
assert np.allclose(_cauchy_riemann(compute_duality_jacobian), target)

