import numpy as np
def _duality(scale, gamma, kp, k0, phi0):
    out = []
    for s, g, k in zip(scale, gamma, kp):
        r = np.array([[np.cos(g), -np.sin(g)], [np.sin(g), np.cos(g)]])
        q = np.array([[np.cos(phi0), -np.sin(phi0)], [np.sin(phi0), np.cos(phi0)]])
        out.append(s * r @ np.diag([1.0, k0 / k]) @ q.T)
    return np.array(out)
def _lsig(out, e):
    out = np.asarray(out, dtype=float)
    if out.shape != (e, 3):
        return -1.0
    w = np.cos(np.arange(1, e + 1, dtype=float))
    return float(np.sum(out[:, 0] * w) + np.sum(out[:, 1] * w[::-1])
                 + np.sum(np.cos(2.0 * out[:, 2]) * w)
                 + np.sum(np.sin(2.0 * out[:, 2]) * w[::-1]))
SC = np.array([0.7, 1.3, 2.2, 0.4, 1.0, 3.1])
GA = np.array([0.3, 1.1, 2.0, 2.9, -0.7, 4.0])
KP = np.array([2.4, 0.3, 1.0, 0.05, 5.0, 0.8])
J = _duality(SC, GA, np.full(6, 1.4), 1.4, 0.4)
def _iso(fn):
    out = np.asarray(fn(J.copy(), 1.4), dtype=float)
    if out.shape != (6, 3):
        return -1.0
    return float(np.sum(out[:, 0]) + 2.0 * np.sum(out[:, 1]) + 10.0 * np.sum(np.abs(out[:, 2])))
assert np.allclose(_iso(realize_duality_laminate), target)

