def _duality(scale, gamma, kp, k0, phi0):
    out = []
    for s, g, k in zip(scale, gamma, kp):
        r = np.array([[np.cos(g), -np.sin(g)], [np.sin(g), np.cos(g)]])
        q = np.array([[np.cos(phi0), -np.sin(phi0)], [np.sin(phi0), np.cos(phi0)]])
        out.append(s * r @ np.diag([1.0, k0 / k]) @ q.T)
