def _lsig(out, e):
    out = np.asarray(out, dtype=float)
    if out.shape != (e, 3):
        return -1.0
    w = np.cos(np.arange(1, e + 1, dtype=float))
    return float(np.sum(out[:, 0] * w) + np.sum(out[:, 1] * w[::-1])
