M=_motion(X)
K[1:]*=0
T[0]=X[:,0]; T[1:]=M[:,:,0]
assert np.allclose(_values(differentiate_duality_response(X.copy(),TR.copy(),K.copy(),T.copy(),1.,.55,node_derivatives=M.copy())), target)

